mapper.select:
select b.bill_id, b.bill_no, b.user_id, b.bill_type, b.amount, b.balance_after, b.related_type, b.related_id, b.remark, b.created_at, o.order_no, w.title as work_title, CASE b.bill_type WHEN 'income' THEN 'settled' WHEN 'settle' THEN 'settled' WHEN 'freeze' THEN 'pending' WHEN 'withdraw' THEN 'settled' ELSE 'settled' END as settle_status from sys_bill_record b left join sys_order o on b.related_type = 'order' and b.related_id = o.order_id left join sys_work w on o.work_id = w.work_id
AND b.user_id = #{userId} AND b.bill_type = #{billType}
order by b.created_at desc

mapper.insert:
insert into sys_bill_record (
    bill_no, user_id, bill_type, amount, balance_after,
    related_type, related_id, remark, create_by, create_time
) values (
    #{billNo}, #{userId}, #{billType}, #{amount}, #{balanceAfter},
    #{relatedType}, #{relatedId}, #{remark}, #{createBy}, #{createTime}
)
